     2→ * User Service (Sequelize ORM)
     3→ *
     4→ * Handles user CRUD operations and user management
     5→ * Migrated from raw SQL queries to Sequelize ORM
     6→ * Phase F: Optimized with eager loading and Sequelize transactions
     7→ */
     8→
     9→import bcrypt from 'bcrypt';
    10→import { User, Role, WhatsAppLine, LineUserAssignment } from '../models/sequelize/associations.js';
    11→import sequelize from '../config/sequelize.js';
    12→
    13→class UserService {
    14→  /**
    15→   * Get all users with pagination and filters
    16→   * OPTIMIZED: Eager loading for Role and assigned WhatsAppLines (eliminates N+1 queries)
    17→   */
    18→  async getAll({ page = 1, limit = 20, role, isActive } = {}) {
    19→    try {
    20→      const offset = (page - 1) * limit;
    21→      const where = {};
    22→      const includeWhere = {};
