/**
 * User Form Component
 *
 * Form for creating/editing users
 * Phase 5: User Story 3 - Agent User Creation and Line Assignment
 */

import { useState, useEffect } from 'react';
import { Form, Button, Alert, Row, Col, InputGroup, Modal, Badge } from 'react-bootstrap';
import PropTypes from 'prop-types';
import Select from 'react-select';
import usePhoneLinesStore from '../../store/phoneLinesStore';
import './UserForm.scss';

const UserForm = ({ user, onSubmit, onCancel, loading, error }) => {
  const { phoneLines, fetchPhoneLines } = usePhoneLinesStore();

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    phoneNumber: '',
    role: 'agent',
    is_active: true,
    selectedLines: []
  });

  const [validated, setValidated] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  useEffect(() => {
    // Fetch phone lines when component mounts
    fetchPhoneLines();
  }, [fetchPhoneLines]);

  useEffect(() => {
    if (user) {
      // assignedLines can be either an array of IDs or an array of objects
      // Ensure all IDs are numbers for consistent comparison
      const lineIds = Array.isArray(user.assignedLines)
        ? user.assignedLines.map(line => {
            const id = typeof line === 'object' ? line.id : line;
            return typeof id === 'string' ? parseInt(id, 10) : id;
          })
        : [];

      setFormData({
        name: user.name || '',
        email: user.email || '',
        password: '', // Don't pre-fill password for security
        phoneNumber: user.phone_number || '',
        role: user.role || 'agent',
        is_active: user.is_active !== undefined ? user.is_active : true,
        selectedLines: lineIds
      });
    }
  }, [user]);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const form = e.currentTarget;

    if (form.checkValidity() === false) {
      e.stopPropagation();
      setValidated(true);
      return;
    }

    // Don't send password if it's empty (editing user)
    const submitData = { ...formData };
    if (user && !submitData.password) {
      delete submitData.password;
    }

    onSubmit(submitData);
  };

  // Helper function to get user initials
  const getUserInitials = () => {
    if (!user || !user.name) return 'U';
    const names = user.name.split(' ');
    if (names.length >= 2) {
      return `${names[0][0]}${names[1][0]}`.toUpperCase();
    }
    return names[0].substring(0, 2).toUpperCase();
  };

  // Helper function to get avatar background color
  const getAvatarColor = () => {
    const colors = ['#8B5CF6', '#3B82F6', '#10B981', '#F59E0B', '#EF4444', '#EC4899'];
    if (!user || !user.name) return colors[0];
    const charCode = user.name.charCodeAt(0);
    return colors[charCode % colors.length];
  };

  return (
    <>
      <Modal.Body className="user-form-body">
        <Form noValidate validated={validated} onSubmit={handleSubmit} id="user-form" className="user-form">
          {error && (
            <Alert variant="danger" dismissible className="mb-4">
              {error}
            </Alert>
          )}

          {/* User Info Header - Only shown when editing */}
          {user && (
            <div className="user-info-header">
              <div className="user-avatar" style={{ backgroundColor: getAvatarColor() }}>
                {getUserInitials()}
              </div>
              <div className="user-info-details">
                <h3 className="user-name">{user.name}</h3>
                <div className="user-contact">
                  <span className="contact-item">
                    <i className="bi bi-envelope"></i> Correo: {user.email}
                  </span>
                  {user.phone_number && (
                    <span className="contact-item">
                      <i className="bi bi-telephone"></i> Teléfono: {user.phone_number}
                    </span>
                  )}
                </div>
              </div>
            </div>
          )}

          <Row>
            <Col md={6}>
              <Form.Group className="mb-3" controlId="name">
                <Form.Label>Nombre</Form.Label>
                <Form.Control
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  required
                  placeholder="Nombre completo"
                  className="form-input"
                />
                <Form.Control.Feedback type="invalid">
                  El nombre es requerido
                </Form.Control.Feedback>
              </Form.Group>
            </Col>

            <Col md={6}>
              <Form.Group className="mb-3" controlId="email">
                <Form.Label>Correo</Form.Label>
                <Form.Control
                  type="email"
                  name="email"
                  value={formData.email}
                  onChange={handleChange}
                  required
                  placeholder="correo@ejemplo.com"
                  className="form-input"
                />
                <Form.Control.Feedback type="invalid">
                  Correo válido es requerido
                </Form.Control.Feedback>
              </Form.Group>
            </Col>
          </Row>

          <Row>
            <Col md={6}>
              <Form.Group className="mb-3" controlId="phoneNumber">
                <Form.Label>Cargo</Form.Label>
                <Form.Control
                  type="text"
                  name="phoneNumber"
                  value={formData.phoneNumber}
                  onChange={handleChange}
                  placeholder="Ej: Analista de selección"
                  className="form-input"
                />
              </Form.Group>
            </Col>

            <Col md={6}>
              <Form.Group className="mb-3" controlId="role">
                <Form.Label>Rol</Form.Label>
                <Form.Select
                  name="role"
                  value={formData.role}
                  onChange={handleChange}
                  required
                  className="form-input"
                >
                  <option value="">Seleccionar rol</option>
                  <option value="agent">Usuario</option>
                  <option value="admin">Administrador</option>
                  <option value="manager">Gestor de plantillas</option>
                </Form.Select>
              </Form.Group>
            </Col>
          </Row>

          {(formData.role === 'agent' || formData.role === 'admin') && (
            <Row>
              <Col md={12}>
                <Form.Group className="mb-3">
                  <Form.Label>Línea de negocio</Form.Label>
                  {phoneLines && phoneLines.length > 0 ? (
                    <>
                      <Select
                        isMulti
                        options={phoneLines.map(line => ({
                          value: line.id,
                          label: `${line.name || line.waba_name || 'Línea'}: ${line.phone_number}`
                        }))}
                        value={phoneLines
                          .filter(line => formData.selectedLines.includes(line.id))
                          .map(line => ({
                            value: line.id,
                            label: `${line.name || line.waba_name || 'Línea'}: ${line.phone_number}`
                          }))}
                        onChange={(selectedOptions) => {
                          const selectedIds = selectedOptions ? selectedOptions.map(opt => opt.value) : [];
                          setFormData(prev => ({ ...prev, selectedLines: selectedIds }));
                        }}
                        className="basic-multi-select"
                        classNamePrefix="select"
                        placeholder="Selecciona una o más líneas..."
                        styles={{
                          control: (base) => ({
                            ...base,
                            borderRadius: '6px',
                            border: '1px solid #d1d5db',
                            minHeight: '42px'
                          })
                        }}
                      />

                      {formData.selectedLines.length > 0 && (
                        <div className="lines-assigned-box">
                          <p className="lines-assigned-text">
                            La línea telefónica asignada es:
                          </p>
                          <ul className="lines-assigned-list">
                            {phoneLines
                              .filter(line => formData.selectedLines.includes(line.id))
                              .map(line => (
                                <li key={line.id}>
                                  <strong>BPO:</strong> {line.phone_number}
                                </li>
                              ))}
                          </ul>
                        </div>
                      )}
                    </>
                  ) : (
                    <p className="text-muted mb-0">No hay líneas telefónicas disponibles</p>
                  )}
                </Form.Group>
              </Col>
            </Row>
          )}

          {!user && (
            <Row>
              <Col md={12}>
                <Form.Group className="mb-3" controlId="password">
                  <Form.Label>Contraseña {user ? '' : '*'}</Form.Label>
                  <InputGroup>
                    <Form.Control
                      type={showPassword ? 'text' : 'password'}
                      name="password"
                      value={formData.password}
                      onChange={handleChange}
                      required={!user}
                      minLength={8}
                      placeholder={user ? 'Dejar en blanco para mantener actual' : 'Ingresar contraseña'}
                      className="form-input"
                    />
                    <Button
                      variant="outline-secondary"
                      onClick={() => setShowPassword(!showPassword)}
                      className="password-toggle"
                    >
                      <i className={`bi ${showPassword ? 'bi-eye-slash' : 'bi-eye'}`}></i>
                    </Button>
                  </InputGroup>
                  <Form.Control.Feedback type="invalid">
                    La contraseña debe tener al menos 8 caracteres
                  </Form.Control.Feedback>
                </Form.Group>
              </Col>
            </Row>
          )}
        </Form>
      </Modal.Body>

      <Modal.Footer className="user-form-footer">
        <Button
          variant="light"
          onClick={onCancel}
          disabled={loading}
          className="btn-cancel"
        >
          Cancelar
        </Button>
        <Button
          variant="warning"
          type="submit"
          form="user-form"
          disabled={loading}
          className="btn-submit"
        >
          {loading ? (
            <>
              <span className="spinner-border spinner-border-sm me-2" />
              {user ? 'Actualizando...' : 'Creando...'}
            </>
          ) : (
            user ? 'Agregar' : 'Agregar'
          )}
        </Button>
      </Modal.Footer>
    </>
  );
};

UserForm.propTypes = {
  user: PropTypes.object,
  onSubmit: PropTypes.func.isRequired,
  onCancel: PropTypes.func.isRequired,
  loading: PropTypes.bool,
  error: PropTypes.string
};

UserForm.defaultProps = {
  user: null,
  loading: false,
  error: null
};

export default UserForm;

