/**
 * User Service (Sequelize ORM)
 *
 * Handles user CRUD operations and user management
 * Migrated from raw SQL queries to Sequelize ORM
 * Phase F: Optimized with eager loading and Sequelize transactions
 */

import bcrypt from 'bcrypt';
import { User, Role, WhatsAppLine, LineUserAssignment } from '../models/sequelize/associations.js';
import sequelize from '../config/sequelize.js';

class UserService {
  /**
   * Get all users with pagination and filters
   * OPTIMIZED: Eager loading for Role and assigned WhatsAppLines (eliminates N+1 queries)
   */
  async getAll({ page = 1, limit = 20, role, isActive } = {}) {
    try {
      const offset = (page - 1) * limit;
      const where = {};
      const includeWhere = {};

      if (isActive !== undefined) where.is_active = isActive;
      if (role) includeWhere.role_name = role;

      const { count, rows: users } = await User.findAndCountAll({
        where,
        include: [
          {
            model: Role,
            as: 'role',
            attributes: ['id', 'role_name'],
            where: Object.keys(includeWhere).length > 0 ? includeWhere : undefined,
            required: Object.keys(includeWhere).length > 0
          },
          {
            model: WhatsAppLine,
            as: 'assignedLines',
            attributes: ['id'],
            through: { attributes: [] },
            required: false
          }
        ],
        attributes: ['id', 'email', 'name', 'phone_number', 'is_active', 'role_id', 'created_at', 'updated_at'],
        limit,
        offset,
        order: [['created_at', 'DESC']],
        distinct: true,
        subQuery: false
      });

      const usersWithLines = users.map((user) => {
        const userJson = user.toJSON();
        userJson.role = user.role.role_name;
        userJson.assignedLines = user.assignedLines?.map(line => line.id) || [];
        return userJson;
      });

      return {
        users: usersWithLines,
        total: count,
        page,
        totalPages: Math.ceil(count / limit)
      };
    } catch (error) {
      console.error('Get users error:', error);
      throw error;
    }
  }

  async getById(userId) {
    try {
      const user = await User.findByPk(userId, {
        include: [
          {
            model: Role,
            as: 'role',
            attributes: ['id', 'role_name']
          },
          {
            model: WhatsAppLine,
            as: 'assignedLines',
            attributes: ['id'],
            through: { attributes: [] },
            required: false
          }
        ],
        attributes: ['id', 'email', 'name', 'phone_number', 'is_active', 'role_id', 'created_at', 'updated_at']
      });

      if (!user) throw new Error('User not found');

      const userJson = user.toJSON();
      userJson.role = user.role.role_name;
      userJson.assignedLines = user.assignedLines?.map(line => line.id) || [];

      return userJson;
    } catch (error) {
      console.error('Get user by ID error:', error);
      throw error;
    }
  }

  async create({ email, password, name, phoneNumber, role }) {
    try {
      if (!['admin', 'agent', 'manager'].includes(role)) {
        throw new Error('Invalid role');
      }

      const roleRecord = await Role.findOne({
        where: { role_name: role },
        attributes: ['id']
      });

      if (!roleRecord) throw new Error('Role not found');

      const existingUser = await User.findOne({
        where: { email },
        attributes: ['id']
      });

      if (existingUser) throw new Error('Email already exists');

      const passwordHash = await bcrypt.hash(password, 12);
      const newUser = await User.create({
        role_id: roleRecord.id,
        email,
        password_hash: passwordHash,
        name,
        phone_number: phoneNumber || null,
        is_active: true
      });

      return await this.getById(newUser.id);
    } catch (error) {
      console.error('Create user error:', error);
      throw error;
    }
  }

  async update(userId, updates) {
    try {
      const user = await User.findByPk(userId);
      if (!user) throw new Error('User not found');

      const allowedFields = ['name', 'phone_number', 'is_active', 'password'];
      const updateData = {};

      for (const [key, value] of Object.entries(updates)) {
        if (allowedFields.includes(key)) {
          if (key === 'password') {
            updateData.password_hash = await bcrypt.hash(value, 12);
          } else {
            updateData[key] = value;
          }
        }
      }

      if (Object.keys(updateData).length === 0) {
        throw new Error('No valid fields to update');
      }

      await user.update(updateData);
      return await this.getById(userId);
    } catch (error) {
      console.error('Update user error:', error);
      throw error;
    }
  }

  async delete(userId) {
    try {
      const user = await User.findByPk(userId);
      if (!user) throw new Error('User not found');

      // Soft delete: mark as inactive instead of hard delete
      // This allows us to provide better error messages on login
      // and maintain data integrity for historical records
      await user.update({ is_active: false });
    } catch (error) {
      console.error('Delete user error:', error);
      throw error;
    }
  }

  async getAssignedLines(userId) {
    try {
      const user = await User.findByPk(userId, {
        include: [
          {
            model: WhatsAppLine,
            as: 'assignedLines',
            attributes: ['id', 'company_name', 'phone_number', 'is_active'],
            through: {
              attributes: ['assigned_at']
            }
          }
        ]
      });

      if (!user) throw new Error('User not found');

      return user.assignedLines.map(line => ({
        id: line.id,
        company_name: line.company_name,
        phone_number: line.phone_number,
        is_active: line.is_active,
        assigned_at: line.LineUserAssignment.assigned_at
      }));
    } catch (error) {
      console.error('Get assigned lines error:', error);
      throw error;
    }
  }

  async assignLines(userId, lineIds) {
    const transaction = await sequelize.transaction();
    try {
      const user = await User.findByPk(userId, {
        include: [{
          model: Role,
          as: 'role',
          attributes: ['role_name']
        }],
        transaction
      });

      if (!user) throw new Error('User not found');
      if (user.role.role_name !== 'agent') {
        throw new Error('Only agents can be assigned lines');
      }

      const assignments = lineIds.map(lineId => ({
        user_id: userId,
        line_id: lineId
      }));

      await LineUserAssignment.bulkCreate(assignments, {
        ignoreDuplicates: true,
        transaction
      });

      await transaction.commit();
    } catch (error) {
      await transaction.rollback();
      console.error('Assign lines error:', error);
      throw error;
    }
  }

  async removeLineAssignment(userId, lineId) {
    try {
      const deleted = await LineUserAssignment.destroy({
        where: {
          user_id: userId,
          line_id: lineId
        }
      });

      if (deleted === 0) {
        throw new Error('Line assignment not found');
      }
    } catch (error) {
      console.error('Remove line assignment error:', error);
      throw error;
    }
  }
}

export default new UserService();

