import { DataTypes } from 'sequelize';
import bcrypt from 'bcrypt';
import sequelize from '../../config/sequelize.js';

/**
 * User Model (Sequelize ORM)
 *
 * Represents platform users (admins and agents) with authentication and authorization.
 * Phase F: Added password hashing hooks (beforeCreate, beforeUpdate)
 */
const User = sequelize.define('User', {
  id: {
    type: DataTypes.INTEGER,
    primaryKey: true,
    autoIncrement: true,
  },
  role_id: {
    type: DataTypes.INTEGER,
    allowNull: false,
    references: {
      model: 'roles',
      key: 'id',
    },
    validate: {
      notNull: {
        msg: 'Role ID is required',
      },
      async isValidRole(value) {
        const { default: Role } = await import('./Role.js');
        const role = await Role.findByPk(value);
        if (!role) {
          throw new Error('Invalid role ID');
        }
      },
    },
  },
  email: {
    type: DataTypes.STRING(255),
    allowNull: false,
    unique: {
      msg: 'Email address already in use',
    },
    validate: {
      isEmail: {
        msg: 'Must be a valid email address',
      },
      notNull: {
        msg: 'Email is required',
      },
      notEmpty: {
        msg: 'Email cannot be empty',
      },
    },
  },
  password_hash: {
    type: DataTypes.STRING(255),
    allowNull: false,
    validate: {
      notNull: {
        msg: 'Password hash is required',
      },
      notEmpty: {
        msg: 'Password hash cannot be empty',
      },
    },
  },
  password: {
    type: DataTypes.VIRTUAL,
    allowNull: true,
    validate: {
      len: {
        args: [8, 255],
        msg: 'Password must be at least 8 characters long',
      },
    },
  },
  name: {
    type: DataTypes.STRING(100),
    allowNull: false,
    validate: {
      notNull: {
        msg: 'Name is required',
      },
      notEmpty: {
        msg: 'Name cannot be empty',
      },
      len: {
        args: [2, 100],
        msg: 'Name must be between 2 and 100 characters',
      },
    },
  },
  phone_number: {
    type: DataTypes.STRING(20),
    allowNull: true,
    validate: {
      is: {
        args: /^\+?[1-9]\d{1,14}$/,
        msg: 'Phone number must be in E.164 format (e.g., +1234567890)',
      },
    },
  },
  is_active: {
    type: DataTypes.BOOLEAN,
    allowNull: false,
    defaultValue: true,
  },
  refresh_token: {
    type: DataTypes.STRING(512),
    allowNull: true,
  },
  refresh_token_expires_at: {
    type: DataTypes.DATE,
    allowNull: true,
  },
}, {
  tableName: 'users',
  timestamps: true,
  createdAt: 'created_at',
  updatedAt: 'updated_at',
  underscored: true,
  indexes: [
    {
      name: 'idx_users_email',
      unique: true,
      fields: ['email'],
    },
    {
      name: 'idx_users_role',
      fields: ['role_id'],
    },
    {
      name: 'idx_users_active',
      fields: ['is_active'],
    },
    {
      name: 'idx_users_refresh_token',
      fields: ['refresh_token'],
    },
  ],
  hooks: {
    beforeCreate: async (user) => {
      if (user.password) {
        user.password_hash = await bcrypt.hash(user.password, 12);
        user.password = undefined;
      }
    },
    beforeUpdate: async (user) => {
      if (user.changed('password') && user.password) {
        user.password_hash = await bcrypt.hash(user.password, 12);
        user.password = undefined;
      }
    },
  },
});

User.prototype.clearRefreshToken = async function () {
  this.refresh_token = null;
  this.refresh_token_expires_at = null;
  await this.save();
};

User.prototype.updateRefreshToken = async function (token, expiresAt) {
  this.refresh_token = token;
  this.refresh_token_expires_at = expiresAt;
  await this.save();
};

User.prototype.isRefreshTokenValid = function () {
  if (!this.refresh_token || !this.refresh_token_expires_at) {
    return false;
  }
  return new Date() < new Date(this.refresh_token_expires_at);
};

User.prototype.comparePassword = async function (password) {
  return await bcrypt.compare(password, this.password_hash);
};

export default User;

