/**
 * POST /api/v1/users
 *
 * Create new user (admin or agent)
 * Phase 5: User Story 3 - Agent User Creation and Line Assignment
 */

import { Router } from 'express';
import UserService from '../../../services/UserService.js';
import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
import { authorizeRole } from '../../../middleware/authorizeRole.js';
import { AppError } from '../../../middleware/errorHandler.js';

const router = Router();

/**
 * @route POST /api/v1/users
 * @desc Create new user
 * @access Admin only
 */
router.post('/', authenticateJWT, authorizeRole(['admin']), async (req, res, next) => {
  try {
    const { email, password, name, phoneNumber, role } = req.body;

    // Validation
    if (!email || !password || !name || !role) {
      throw new AppError('Missing required fields: email, password, name, role', 400);
    }

    if (!['admin', 'agent', 'manager'].includes(role)) {
      throw new AppError('Invalid role. Must be admin, agent, or manager', 400);
    }

    if (password.length < 8) {
      throw new AppError('Password must be at least 8 characters', 400);
    }

    // Email validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      throw new AppError('Invalid email format', 400);
    }

    const newUser = await UserService.create({
      email,
      password,
      name,
      phoneNumber,
      role
    });

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: newUser
    });
  } catch (error) {
    next(error);
  }
});

export default router;

