/**
 * Request Validation Middleware
 *
 * Provides validation helpers for request body, query, and params
 * Uses simple validation rules without external dependencies
 */

import AppError from './errorHandler.js';

/**
 * Validation rules
 */
export const validators = {
  /**
   * Check if value is required
   */
  required: (value, fieldName) => {
    if (value === undefined || value === null || value === '') {
      throw new AppError(`${fieldName} is required`, 400);
    }
    return true;
  },

  /**
   * Check if value is a valid email
   */
  email: (value, fieldName) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(value)) {
      throw new AppError(`${fieldName} must be a valid email address`, 400);
    }
    return true;
  },

  /**
   * Check minimum length
   */
  minLength: (value, fieldName, min) => {
    if (value && value.length < min) {
      throw new AppError(`${fieldName} must be at least ${min} characters`, 400);
    }
    return true;
  },

  /**
   * Check maximum length
   */
  maxLength: (value, fieldName, max) => {
    if (value && value.length > max) {
      throw new AppError(`${fieldName} must not exceed ${max} characters`, 400);
    }
    return true;
  },

  /**
   * Check if value is a number
   */
  isNumber: (value, fieldName) => {
    if (isNaN(Number(value))) {
      throw new AppError(`${fieldName} must be a number`, 400);
    }
    return true;
  },

  /**
   * Check if value is an integer
   */
  isInteger: (value, fieldName) => {
    if (!Number.isInteger(Number(value))) {
      throw new AppError(`${fieldName} must be an integer`, 400);
    }
    return true;
  },

  /**
   * Check if value is a boolean
   */
  isBoolean: (value, fieldName) => {
    if (typeof value !== 'boolean' && value !== 'true' && value !== 'false') {
      throw new AppError(`${fieldName} must be a boolean`, 400);
    }
    return true;
  },

  /**
   * Check if value is in allowed values
   */
  isIn: (value, fieldName, allowedValues) => {
    if (!allowedValues.includes(value)) {
      throw new AppError(
        `${fieldName} must be one of: ${allowedValues.join(', ')}`,
        400
      );
    }
    return true;
  },

  /**
   * Check if value matches regex pattern
   */
  matches: (value, fieldName, pattern, message) => {
    if (!pattern.test(value)) {
      throw new AppError(message || `${fieldName} format is invalid`, 400);
    }
    return true;
  },

  /**
   * Check if value is a valid phone number (E.164 format)
   */
  phone: (value, fieldName) => {
    const phoneRegex = /^\+[1-9]\d{1,14}$/;
    if (!phoneRegex.test(value)) {
      throw new AppError(
        `${fieldName} must be a valid phone number in E.164 format (e.g., +1234567890)`,
        400
      );
    }
    return true;
  },

  /**
   * Check if value is a valid URL
   */
  url: (value, fieldName) => {
    try {
      new URL(value);
      return true;
    } catch (err) {
      throw new AppError(`${fieldName} must be a valid URL`, 400);
    }
  },

  /**
   * Check minimum value (for numbers)
   */
  min: (value, fieldName, minValue) => {
    if (Number(value) < minValue) {
      throw new AppError(`${fieldName} must be at least ${minValue}`, 400);
    }
    return true;
  },

  /**
   * Check maximum value (for numbers)
   */
  max: (value, fieldName, maxValue) => {
    if (Number(value) > maxValue) {
      throw new AppError(`${fieldName} must not exceed ${maxValue}`, 400);
    }
    return true;
  }
};

/**
 * Validate request based on schema
 *
 * Schema format:
 * {
 *   fieldName: {
 *     in: ['body', 'query', 'params'], // where to find the field
 *     required: true,
 *     email: true,
 *     minLength: 8,
 *     custom: (value) => { ... } // custom validator
 *   }
 * }
 *
 * @param {Object} schema - Validation schema
 * @returns {Function} Express middleware
 */
export const validateRequest = (schema) => {
  return (req, res, next) => {
    try {
      const errors = [];

      for (const [fieldName, rules] of Object.entries(schema)) {
        // Determine where to look for the field
        const sources = rules.in || ['body'];
        let value;
        let found = false;

        for (const source of sources) {
          if (req[source] && req[source][fieldName] !== undefined) {
            value = req[source][fieldName];
            found = true;
            break;
          }
        }

        // Check required
        if (rules.required) {
          try {
            validators.required(value, fieldName);
          } catch (err) {
            errors.push(err.message);
            continue; // Skip other validations if required fails
          }
        }

        // Skip other validations if value is not present and not required
        if (!found && !rules.required) {
          continue;
        }

        // Apply validation rules
        try {
          if (rules.email) validators.email(value, fieldName);
          if (rules.phone) validators.phone(value, fieldName);
          if (rules.url) validators.url(value, fieldName);
          if (rules.isNumber) validators.isNumber(value, fieldName);
          if (rules.isInteger) validators.isInteger(value, fieldName);
          if (rules.isBoolean) validators.isBoolean(value, fieldName);
          if (rules.minLength) validators.minLength(value, fieldName, rules.minLength);
          if (rules.maxLength) validators.maxLength(value, fieldName, rules.maxLength);
          if (rules.min !== undefined) validators.min(value, fieldName, rules.min);
          if (rules.max !== undefined) validators.max(value, fieldName, rules.max);
          if (rules.isIn) validators.isIn(value, fieldName, rules.isIn);
          if (rules.matches) {
            validators.matches(
              value,
              fieldName,
              rules.matches.pattern,
              rules.matches.message
            );
          }

          // Custom validator
          if (rules.custom) {
            const customResult = rules.custom(value, req);
            if (customResult !== true && typeof customResult === 'string') {
              errors.push(customResult);
            }
          }
        } catch (err) {
          errors.push(err.message);
        }
      }

      // If there are validation errors, throw them
      if (errors.length > 0) {
        throw new AppError(errors.join('; '), 400);
      }

      next();
    } catch (err) {
      next(err);
    }
  };
};

/**
 * Sanitize request data
 * Removes fields not in allowedFields
 *
 * @param {string} source - 'body', 'query', or 'params'
 * @param {Array} allowedFields - Array of allowed field names
 * @returns {Function} Express middleware
 */
export const sanitizeRequest = (source, allowedFields) => {
  return (req, res, next) => {
    if (req[source]) {
      const sanitized = {};
      for (const field of allowedFields) {
        if (req[source][field] !== undefined) {
          sanitized[field] = req[source][field];
        }
      }
      req[source] = sanitized;
    }
    next();
  };
};

/**
 * Common validation schemas
 */
export const commonSchemas = {
  // Pagination
  pagination: {
    page: {
      in: ['query'],
      isInteger: true,
      min: 1
    },
    limit: {
      in: ['query'],
      isInteger: true,
      min: 1,
      max: 100
    }
  },

