/**
 * PATCH /api/v1/users/:userId
 *
 * Update user information
 * Phase 5: User Story 3 - Agent User Creation and Line Assignment
 */

import { Router } from 'express';
import UserService from '../../../services/UserService.js';
import { authenticateJWT } from '../../../middleware/authenticateJWT.js';
import { authorizeRole } from '../../../middleware/authorizeRole.js';
import { AppError } from '../../../middleware/errorHandler.js';

const router = Router();

/**
 * @route PATCH /api/v1/users/:userId
 * @desc Update user information
 * @access Admin only
 */
router.patch('/:userId', authenticateJWT, authorizeRole(['admin']), async (req, res, next) => {
  try {
    const { userId } = req.params;
    const updates = req.body;

    if (!userId || isNaN(parseInt(userId))) {
      throw new AppError('Invalid user ID', 400);
    }

    // Validate password length if provided
    if (updates.password && updates.password.length < 8) {
      throw new AppError('Password must be at least 8 characters', 400);
    }

    // Validate is_active is boolean if provided
    if (updates.is_active !== undefined && typeof updates.is_active !== 'boolean') {
      throw new AppError('is_active must be a boolean', 400);
    }

    const updatedUser = await UserService.update(parseInt(userId), updates);

    res.status(200).json({
      success: true,
      message: 'User updated successfully',
      data: updatedUser
    });
  } catch (error) {
    next(error);
  }
});

export default router;

