/**
 * Users Store (Zustand)
 *
 * State management for user management
 * Phase 5: User Story 3 - Agent User Creation and Line Assignment
 */

import { create } from 'zustand';
import userService from '../services/userService';

const useUsersStore = create((set, get) => ({
  // State
  users: [],
  selectedUser: null,
  loading: false,
  error: null,
  pagination: {
    page: 1,
    limit: 20,
    total: 0,
    totalPages: 0
  },

  // Actions

  /**
   * Fetch all users
   */
  fetchUsers: async (params = {}) => {
    set({ loading: true, error: null });
    try {
      const response = await userService.getUsers(params);
      set({
        users: response.data || [],
        pagination: response.pagination || {},
        loading: false
      });
    } catch (error) {
      set({
        error: error.message || 'Failed to fetch users',
        loading: false
      });
    }
  },

  /**
   * Fetch single user by ID
   */
  fetchUserById: async (userId) => {
    set({ loading: true, error: null });
    try {
      const response = await userService.getUserById(userId);
      set({
        selectedUser: response.data,
        loading: false
      });
      return response.data;
    } catch (error) {
      set({
        error: error.message || 'Failed to fetch user',
        loading: false
      });
      throw error;
    }
  },

  /**
   * Create new user
   */
  createUser: async (userData) => {
    set({ loading: true, error: null });
    try {
      const response = await userService.createUser(userData);

      // Add new user to state
      set(state => ({
        users: [response.data, ...state.users],
        loading: false
      }));

      return response.data;
    } catch (error) {
      set({
        error: error.message || 'Failed to create user',
        loading: false
      });
      throw error;
    }
  },

  /**
   * Update existing user
   */
  updateUser: async (userId, updateData) => {
    set({ loading: true, error: null });
    try {
      const response = await userService.updateUser(userId, updateData);

      // Update user in state
      set(state => ({
        users: state.users.map(user =>
          user.id === userId ? response.data : user
        ),
        selectedUser: state.selectedUser?.id === userId ? response.data : state.selectedUser,
        loading: false
      }));

      return response.data;
    } catch (error) {
      set({
        error: error.message || 'Failed to update user',
        loading: false
      });
      throw error;
    }
  },

  /**
   * Delete user (soft delete - marks as inactive)
   */
  deleteUser: async (userId) => {
    set({ loading: true, error: null });
    try {
      await userService.deleteUser(userId);

      // Fetch updated user to reflect is_active = false
      const response = await userService.getUserById(userId);

      // Update user in state with new is_active status
      set(state => ({
        users: state.users.map(user =>
          user.id === userId ? { ...user, ...response.data, is_active: false } : user
        ),
        selectedUser: state.selectedUser?.id === userId ? null : state.selectedUser,
        loading: false
      }));
    } catch (error) {
      set({
        error: error.message || 'Failed to delete user',
        loading: false
      });
      throw error;
    }
  },

  /**
   * Activate user (marks as active)
   */
  activateUser: async (userId) => {
    set({ loading: true, error: null });
    try {
      await userService.activateUser(userId);

      // Fetch updated user to reflect is_active = true
      const response = await userService.getUserById(userId);

      // Update user in state with new is_active status
      set(state => ({
        users: state.users.map(user =>
          user.id === userId ? { ...user, ...response.data, is_active: true } : user
        ),
        loading: false
      }));

      return response.data;
    } catch (error) {
      set({
        error: error.message || 'Failed to activate user',
        loading: false
      });
      throw error;
    }
  },

  /**
   * Get assigned lines for a user
   */
  fetchUserAssignedLines: async (userId) => {
    try {
      const response = await userService.getUserAssignedLines(userId);
      return response.data || [];
    } catch (error) {
      set({ error: error.message || 'Failed to fetch assigned lines' });
      throw error;
    }
  },

  /**
   * Assign lines to a user
   */
  assignLinesToUser: async (userId, lineIds) => {
    set({ loading: true, error: null });
    try {
      await userService.assignLinesToUser(userId, lineIds);

      // Refresh user data to get updated line assignments
      const response = await userService.getUserById(userId);
      set(state => ({
        users: state.users.map(user =>
          user.id === userId ? response.data : user
        ),
        selectedUser: state.selectedUser?.id === userId ? response.data : state.selectedUser,
        loading: false
      }));
    } catch (error) {
      set({
        error: error.message || 'Failed to assign lines',
        loading: false
      });
      throw error;
    }
  },

  /**
   * Remove line assignment from user
   */
  removeLineFromUser: async (userId, lineId) => {
    set({ loading: true, error: null });
    try {
      await userService.removeLineFromUser(userId, lineId);

      // Refresh user data to get updated line assignments
      const response = await userService.getUserById(userId);
      set(state => ({
        users: state.users.map(user =>
          user.id === userId ? response.data : user
        ),
        selectedUser: state.selectedUser?.id === userId ? response.data : state.selectedUser,
        loading: false
      }));
    } catch (error) {
      set({
        error: error.message || 'Failed to remove line assignment',
        loading: false
      });
      throw error;
    }
  },

  /**
   * Clear error
   */
  clearError: () => set({ error: null }),

  /**
   * Set selected user
   */
  setSelectedUser: (user) => set({ selectedUser: user }),

  /**
   * Clear selected user
   */
  clearSelectedUser: () => set({ selectedUser: null })
}));

export default useUsersStore;

