/**
 * User Service
 *
 * API service for user management
 * Phase 5: User Story 3 - Agent User Creation and Line Assignment
 */

import api from './api';

/**
 * Get all users
 *
 * @param {Object} params - Query parameters
 * @param {number} params.page - Page number
 * @param {number} params.limit - Items per page
 * @param {string} params.role - Filter by role (admin or agent)
 * @param {boolean} params.is_active - Filter by active status
 * @returns {Promise<Object>} Users data with pagination
 */
export const getUsers = async (params = {}) => {
  try {
    const response = await api.get('/users', { params });
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to fetch users');
  }
};

/**
 * Get single user by ID
 *
 * @param {number} userId - User ID
 * @returns {Promise<Object>} User data
 */
export const getUserById = async (userId) => {
  try {
    const response = await api.get(`/users/${userId}`);
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to fetch user');
  }
};

/**
 * Create new user
 *
 * @param {Object} userData - User data
 * @param {string} userData.email - User email
 * @param {string} userData.password - User password
 * @param {string} userData.name - User name
 * @param {string} userData.phoneNumber - User phone number (optional)
 * @param {string} userData.role - User role (admin or agent)
 * @returns {Promise<Object>} Created user
 */
export const createUser = async (userData) => {
  try {
    const response = await api.post('/users', userData);
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to create user');
  }
};

/**
 * Update user
 *
 * @param {number} userId - User ID
 * @param {Object} updateData - Fields to update
 * @returns {Promise<Object>} Updated user
 */
export const updateUser = async (userId, updateData) => {
  try {
    const response = await api.patch(`/users/${userId}`, updateData);
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to update user');
  }
};

/**
 * Delete user
 *
 * @param {number} userId - User ID
 * @returns {Promise<Object>} Deletion result
 */
export const deleteUser = async (userId) => {
  try {
    const response = await api.delete(`/users/${userId}`);
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to delete user');
  }
};

/**
 * Activate user
 *
 * @param {number} userId - User ID
 * @returns {Promise<Object>} Activated user
 */
export const activateUser = async (userId) => {
  try {
    const response = await api.put(`/users/${userId}/activate`);
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to activate user');
  }
};

/**
 * Get lines assigned to a user
 *
 * @param {number} userId - User ID
 * @returns {Promise<Array>} Assigned lines
 */
export const getUserAssignedLines = async (userId) => {
  try {
    const response = await api.get(`/users/${userId}/lines`);
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to fetch assigned lines');
  }
};

/**
 * Assign lines to a user
 *
 * @param {number} userId - User ID
 * @param {number[]} lineIds - Array of line IDs to assign
 * @returns {Promise<Object>} Assignment result
 */
export const assignLinesToUser = async (userId, lineIds) => {
  try {
    const response = await api.post(`/users/${userId}/lines`, { lineIds });
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to assign lines');
  }
};

/**
 * Remove line assignment from user
 *
 * @param {number} userId - User ID
 * @param {number} lineId - Line ID to remove
 * @returns {Promise<Object>} Removal result
 */
export const removeLineFromUser = async (userId, lineId) => {
  try {
    const response = await api.delete(`/users/${userId}/lines/${lineId}`);
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to remove line assignment');
  }
};



/**
 * Get current authenticated user's assigned lines
 * For agents, returns only their assigned lines
 * For admins, returns all lines plus their personal assignments
 *
 * @returns {Promise<Object>} Lines data { all_lines?, assigned_lines }
 */
export const getMyAssignedLines = async () => {
  try {
    const response = await api.get('/users/me/lines');
    return response.data.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to fetch my assigned lines');
  }
};

/**
 * Get agents assigned to a specific line
 *
 * @param {number} lineId - Line ID
 * @returns {Promise<Array>} Array of agents
 */
export const getAgentsByLine = async (lineId) => {
  try {
    const response = await api.get(`/users/agents/line/${lineId}`);
    return response.data;
  } catch (error) {
    throw new Error(error.response?.data?.error || 'Failed to fetch agents for line');
  }
};

export default {
  getUsers,
  getUserById,
  createUser,
  updateUser,
  deleteUser,
  activateUser,
  getUserAssignedLines,
  assignLinesToUser,
  removeLineFromUser,
  getMyAssignedLines,
  getAgentsByLine
};

